-- TRANSITIQ baseline schema for a fresh Supabase project.
create extension if not exists pgcrypto;
create table if not exists public.admin_users(user_id uuid primary key references auth.users(id) on delete cascade,created_at timestamptz not null default now());
create table if not exists public.stops(id text primary key,name text not null unique,area text not null,latitude double precision not null,longitude double precision not null,created_at timestamptz not null default now());
create table if not exists public.routes(id text primary key,route_number text not null unique,name text not null,average_speed numeric(6,2) not null default 25,status text not null default 'Active',created_at timestamptz not null default now());
create table if not exists public.buses(id text primary key,registration_number text not null unique,name text not null,bus_type text not null check(bus_type in('Ordinary','Express','AC')),capacity integer not null check(capacity>0),driver_name text not null default '',assigned_route_id text references public.routes(id) on delete set null,status text not null default 'Active',created_at timestamptz not null default now());
create table if not exists public.route_stops(id bigint generated by default as identity primary key,route_id text not null references public.routes(id) on delete cascade,stop_id text not null references public.stops(id) on delete restrict,sequence_number integer not null,distance_from_previous_km numeric(8,2) not null default 0,unique(route_id,sequence_number),unique(route_id,stop_id));
create table if not exists public.route_buses(route_id text not null references public.routes(id) on delete cascade,bus_id text not null references public.buses(id) on delete cascade,primary key(route_id,bus_id));
create table if not exists public.fare_settings(bus_type text primary key,rate_per_km numeric(8,2) not null,minimum_fare numeric(8,2) not null,updated_at timestamptz not null default now());
create table if not exists public.bus_locations(bus_id text primary key references public.buses(id) on delete cascade,latitude double precision not null,longitude double precision not null,simulated_speed numeric(6,2) not null default 0,simulation_status text not null default 'simulated',last_updated timestamptz not null default now());
create table if not exists public.journey_searches(id uuid primary key default gen_random_uuid(),source_stop_id text not null references public.stops(id),destination_stop_id text not null references public.stops(id),distance_km numeric(8,2) not null,estimated_duration_minutes integer not null,estimated_fare numeric(10,2) not null,searched_at timestamptz not null default now());
alter table public.admin_users enable row level security;
alter table public.stops enable row level security; alter table public.routes enable row level security; alter table public.buses enable row level security; alter table public.route_stops enable row level security; alter table public.route_buses enable row level security; alter table public.fare_settings enable row level security; alter table public.bus_locations enable row level security; alter table public.journey_searches enable row level security;
create policy "Public can read stops" on public.stops for select to anon,authenticated using(true);
create policy "Admins manage stops" on public.stops for all to authenticated using(exists(select 1 from public.admin_users a where a.user_id=(select auth.uid()))) with check(exists(select 1 from public.admin_users a where a.user_id=(select auth.uid())));
create policy "Public can read routes" on public.routes for select to anon,authenticated using(true);
create policy "Admins manage routes" on public.routes for all to authenticated using(exists(select 1 from public.admin_users a where a.user_id=(select auth.uid()))) with check(exists(select 1 from public.admin_users a where a.user_id=(select auth.uid())));
create policy "Public can read buses" on public.buses for select to anon,authenticated using(true);
create policy "Admins manage buses" on public.buses for all to authenticated using(exists(select 1 from public.admin_users a where a.user_id=(select auth.uid()))) with check(exists(select 1 from public.admin_users a where a.user_id=(select auth.uid())));
create policy "Public can read route stops" on public.route_stops for select to anon,authenticated using(true);
create policy "Admins manage route stops" on public.route_stops for all to authenticated using(exists(select 1 from public.admin_users a where a.user_id=(select auth.uid()))) with check(exists(select 1 from public.admin_users a where a.user_id=(select auth.uid())));
create policy "Public can read route buses" on public.route_buses for select to anon,authenticated using(true);
create policy "Admins manage route buses" on public.route_buses for all to authenticated using(exists(select 1 from public.admin_users a where a.user_id=(select auth.uid()))) with check(exists(select 1 from public.admin_users a where a.user_id=(select auth.uid())));
create policy "Public can read fares" on public.fare_settings for select to anon,authenticated using(true);
create policy "Admins manage fares" on public.fare_settings for all to authenticated using(exists(select 1 from public.admin_users a where a.user_id=(select auth.uid()))) with check(exists(select 1 from public.admin_users a where a.user_id=(select auth.uid())));
create policy "Public can read locations" on public.bus_locations for select to anon,authenticated using(true);
create policy "Admins manage locations" on public.bus_locations for all to authenticated using(exists(select 1 from public.admin_users a where a.user_id=(select auth.uid()))) with check(exists(select 1 from public.admin_users a where a.user_id=(select auth.uid())));
create policy "Public can record journey searches" on public.journey_searches for insert to anon,authenticated with check(true);
create policy "Admins can read journey searches" on public.journey_searches for select to authenticated using(exists(select 1 from public.admin_users a where a.user_id=(select auth.uid())));
create policy "Admins can read own admin record" on public.admin_users for select to authenticated using(user_id=(select auth.uid()));
grant select on public.stops,public.routes,public.buses,public.route_stops,public.route_buses,public.fare_settings,public.bus_locations to anon,authenticated;
grant insert on public.journey_searches to anon,authenticated;
grant select on public.journey_searches,public.admin_users to authenticated;
grant insert,update,delete on public.stops,public.routes,public.buses,public.route_stops,public.route_buses,public.fare_settings,public.bus_locations to authenticated;
